import importlib.util
from pathlib import Path

spec = importlib.util.spec_from_file_location('v9_screens', Path(__file__).resolve().parent.parent / 'HB-42-auto-pricing/screens.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


def additions(locale):
    t = lambda en, ko: ko if locale == 'ko' else en
    pages = module.additions(locale)

    def link(key, en, ko):
        return f'<a href="#{key}">{t(en, ko)} →</a>'

    def table(headers, rows):
        return '<div class="table-scroll" tabindex="0"><table><thead><tr>' + ''.join('<th>' + t(*h) + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + str(v) + '</td>' for v in r) + '</tr>' for r in rows) + '</tbody></table></div>'

    def form(items):
        return '<div class="auto-form">' + ''.join('<label>' + t(*label) + '<input placeholder="' + t(*placeholder) + '" value="' + t(*value) + '"></label>' for label, placeholder, value in items) + '</div>'

    def note(en, ko):
        return '<div class="auto-note">' + t(en, ko) + '</div>'

    def button(en, ko):
        return '<button>' + t(en, ko) + '</button>'

    def page(key, title, lead, body):
        pages[key] = '<h1>' + t(*title) + '</h1><p class="lead">' + t(*lead) + '</p>' + body

