    body = form([(('Installation proof','설치 등록 증명'),('Provided by authorized operator; never shown in logs','설치 담당자가 전달 · 로그에 표시하지 않음'),('','')),(('Administrator identity','최초 관리자 신원'),('Approved identity method','승인된 신원 확인 방식'),('',''))])
    body += button('Verify and create initial administrator','확인 후 최초 관리자 생성')
    body += table([('State','상태'),('Expected behavior','처리 기준')],[[t('Valid, unused installation proof','유효한 미사용 설치 증명'),t('One atomic consumption creates one bounded administrator','원자적 1회 사용으로 제한된 초기 관리자 1명 생성')],[t('Expired / revoked / consumed','만료 / 회수 / 사용 완료'),t('Reject; request authorized reissue, invalidating old proof','거부 · 권한 있는 재발급 요청 · 이전 증명 폐기')],[t('Concurrent use','동시 사용'),t('One succeeds; remaining attempts reject','1건만 성공 · 나머지는 거부')],[t('Wrong installation / purpose','설치 대상 / 용도 불일치'),t('Reject without revealing installation details','설치 정보를 노출하지 않고 거부')]])
